mapper.select:
select A.*, B.username, CASE A.order_type WHEN 2 THEN G.name ELSE T.title END as title, CASE A.order_type WHEN 2 THEN G.img ELSE T.cover END as cover, CASE A.order_type WHEN 2 THEN G.price ELSE T.price END as price from `order` as A join `user` as B on (A.user_id=B.id) left join pet_product as T on (A.product_id=T.id AND A.order_type = 1) left join goods as G on (A.product_id=G.id AND A.order_type = 2) where 2>1
and A.user_id=#{userId}
and A.status=#{status}
order by A.order_time desc;
